(5746762, 836228, 96751, '<td valign="top">Fabulous.  This should be very popular.  Love the processing.</td>', 'Fabulous.  This should be very popular.  Love the processing.', '2009-11-30 12:23:12.000000', NULL, 1),
(5746764, 835893, 96751, '<td valign="top">Terrific perspective.  Love the cloud of dots from the skirt.</td>', 'Terrific perspective.  Love the cloud of dots from the skirt.', '2009-11-30 12:24:23.000000', NULL, 1),
(5746793, 836505, 83313, '<td valign="top">Something escaping from a purse? A banana? An "adult novelty item"? Not quite sure what I am looking at.</td>', 'Something escaping from a purse? A banana? An "adult novelty item"? Not quite sure what I am looking at.', '2009-11-30 12:59:36.000000', NULL, 1),
(5746797, 836236, 83313, '<td valign="top">A little out of the box, but it does have a polka dot look to it.</td>', 'A little out of the box, but it does have a polka dot look to it.', '2009-11-30 13:01:01.000000', NULL, 1),
(5746799, 836493, 83313, '<td valign="top">I like the image, though I am not sure that I consider bokeh to be a form of polka dots.</td>', 'I like the image, though I am not sure that I consider bokeh to be a form of polka dots.', '2009-11-30 13:02:15.000000', NULL, 1),
(5746803, 836137, 83313, '<td valign="top">Very nice abstract, but I have a hard time classifying bokeh as a form of polka dots.</td>', 'Very nice abstract, but I have a hard time classifying bokeh as a form of polka dots.', '2009-11-30 13:03:21.000000', NULL, 1),
(5746805, 835627, 83313, '<td valign="top">Nice abstract bokeh, but as with the others, I can''t fit bokeh into my definition of polka dots. Sorry.</td>', 'Nice abstract bokeh, but as with the others, I can''t fit bokeh into my definition of polka dots. Sorry.', '2009-11-30 13:05:22.000000', NULL, 1),
(5746808, 836157, 83313, '<td valign="top">Oddly engaging. Not totally sure what to make of this.</td>', 'Oddly engaging. Not totally sure what to make of this.', '2009-11-30 13:07:34.000000', NULL, 1),
(5746810, 836202, 83313, '<td valign="top">NOOOOOO!!!! Stay away from the dots! They lead to the kitchen at Red Lobster! Save yourself!</td>', 'NOOOOOO!!!! Stay away from the dots! They lead to the kitchen at Red Lobster! Save yourself!', '2009-11-30 13:10:52.000000', NULL, 1),
(5746814, 836574, 83313, '<td valign="top">I''ll go along with the cowboy and polka dots, but if I ever find one wearing pink flip-flops, I''m moving to another state. First rate portrait, BTW.</td>', 'I''ll go along with the cowboy and polka dots, but if I ever find one wearing pink flip-flops, I''m moving to another state. First rate portrait, BTW.', '2009-11-30 13:13:04.000000', NULL, 1),
(5746816, 836248, 83313, '<td valign="top">What an interesting "slice of life" photo. I like it.</td>', 'What an interesting "slice of life" photo. I like it.', '2009-11-30 13:13:54.000000', NULL, 1),
(5746818, 836170, 83313, '<td valign="top">Cute bunch of kids. Good use of color and the blur as well.</td>', 'Cute bunch of kids. Good use of color and the blur as well.', '2009-11-30 13:14:47.000000', NULL, 1),
(5746820, 836196, 83313, '<td valign="top">Looks like it came out of an old advertisement. I''ll bet her name is "Dotty". Nice work.</td>', 'Looks like it came out of an old advertisement. I''ll bet her name is "Dotty". Nice work.', '2009-11-30 13:16:20.000000', NULL, 1),
(5746824, 836026, 83313, '<td valign="top">*sigh* If I see another wine glass shot in a challenge, I''m gonna... well, not today. Good is good.</td>', '*sigh* If I see another wine glass shot in a challenge, I''m gonna... well, not today. Good is good.', '2009-11-30 13:18:46.000000', NULL, 1),
(5746828, 836210, 83313, '<td valign="top">Very appropriate for the character. You know this one will do well, they always do. I''m curious if you painted the van especially for this challenge topic, or if that''s the way it was.</td>', 'Very appropriate for the character. You know this one will do well, they always do. I''m curious if you painted the van especially for this challenge topic, or if that''s the way it was.', '2009-11-30 13:21:44.000000', NULL, 1),
(5746834, 836501, 83313, '<td valign="top">Doesn''t strike me as fitting my idea of polka dots, and the image itself is just not grabbing my attention either. Sorry. Have to credit you for an OOTB effort, however.</td>', 'Doesn''t strike me as fitting my idea of polka dots, and the image itself is just not grabbing my attention either. Sorry. Have to credit you for an OOTB effort, however.', '2009-11-30 13:23:48.000000', NULL, 1),
(5746838, 836467, 83313, '<td valign="top">Good clarity and subject, though the lighting seems a little harsh on it.</td>', 'Good clarity and subject, though the lighting seems a little harsh on it.', '2009-11-30 13:24:35.000000', NULL, 1),
(5746841, 836496, 83313, '<td valign="top">Seems a bit soft and the colors don''t seem to have much punch for me. Not totally sure what it is or is not because of.</td>', 'Seems a bit soft and the colors don''t seem to have much punch for me. Not totally sure what it is or is not because of.', '2009-11-30 13:26:25.000000', NULL, 1),
