(5751392, 836170, 105441, '<td valign="top">Nice portraits, but it lacks a strong connection to the polka dot theme.  The eye is drawn to the great expressions, and only two of three kids are sporting the challenge theme.</td>', 'Nice portraits, but it lacks a strong connection to the polka dot theme.  The eye is drawn to the great expressions, and only two of three kids are sporting the challenge theme.', '2009-12-02 21:27:09.000000', NULL, 1),
(5751394, 836328, 105441, '<td valign="top">Clowns scare me, even in B&amp;W.  Nice dots, though.</td>', 'Clowns scare me, even in B&W.  Nice dots, though.', '2009-12-02 21:28:31.000000', NULL, 1),
(5751396, 835383, 105441, '<td valign="top">I like the unconventional framing, and the understated use of the dots.</td>', 'I like the unconventional framing, and the understated use of the dots.', '2009-12-02 21:29:21.000000', NULL, 1),
(5751399, 836248, 108982, '<td valign="top">nice capture.  great idea but I feel left wondering what the rest of the story is.  Although the photo in itself is good it makes me want to know more.  Did a first boyfriend win the fish for her?  Is she happy with her prize? It looks like a really interesting wall behind that could have been used more creatively...Still all in all a 7 in my humble opinion.</td>', 'nice capture.  great idea but I feel left wondering what the rest of the story is.  Although the photo in itself is good it makes me want to know more.  Did a first boyfriend win the fish for her?  Is she happy with her prize? It looks like a really interesting wall behind that could have been used more creatively...Still all in all a 7 in my humble opinion.', '2009-12-02 21:30:59.000000', NULL, 1),
(5751400, 836427, 108982, '<td valign="top">interesting interpretation of Polka Dots.  I''m not sure it meets the challenge but I love the intense saturation of green, it works. 7</td>', 'interesting interpretation of Polka Dots.  I''m not sure it meets the challenge but I love the intense saturation of green, it works. 7', '2009-12-02 21:32:27.000000', NULL, 1),
(5751404, 836170, 108982, '<td valign="top">This reminds me of a Librodo capture.  Strong use of the child''s emotions.  very heartwarming.  Nice 7</td>', 'This reminds me of a Librodo capture.  Strong use of the child''s emotions.  very heartwarming.  Nice 7', '2009-12-02 21:35:41.000000', NULL, 1),
(5751407, 836279, 105441, '<td valign="top">Great portrait - lighting, subject, expression, and framing are excellent.  Not a strong use of the theme, though.</td>', 'Great portrait - lighting, subject, expression, and framing are excellent.  Not a strong use of the theme, though.', '2009-12-02 21:36:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5751414, 836051, 105441, '<td valign="top">Great location, but the photo has too many distractions with the wires and such.</td>', 'Great location, but the photo has too many distractions with the wires and such.', '2009-12-02 21:38:09.000000', NULL, 1),
(5751421, 835893, 108982, '<td valign="top">Nice top-down camera position.  I really like the quality and range of grays presented in this capture.  Refreshing smile and very fitting title.  It''s nice to see a subtle use of the "dots".  Cool 8</td>', 'Nice top-down camera position.  I really like the quality and range of grays presented in this capture.  Refreshing smile and very fitting title.  It''s nice to see a subtle use of the "dots".  Cool 8', '2009-12-02 21:41:26.000000', NULL, 1),
(5751439, 836202, 103142, '<td valign="top">would be much better if you could have glued the dots down more. The fact that they''re separating from the cloth ruins the effect.</td>', 'would be much better if you could have glued the dots down more. The fact that they''re separating from the cloth ruins the effect.', '2009-12-02 21:50:23.000000', NULL, 1),
(5751442, 836135, 108982, '<td valign="top">This picture would have been my favorite in the group except for two things.  First the pluses...Superb model.  The right age and shape with a great pose.  Photo quality is perfect and focus is good.<br/>My minor retractions...the sandal tweaked out from the foot draws too much attention and the heavily patterned umbrella is in my humble opinion much too busy for the head scarf and shirt.  still a pretty nice capture. 7</td>', 'This picture would have been my favorite in the group except for two things.  First the pluses...Superb model.  The right age and shape with a great pose.  Photo quality is perfect and focus is good.My minor retractions...the sandal tweaked out from the foot draws too much attention and the heavily patterned umbrella is in my humble opinion much too busy for the head scarf and shirt.  still a pretty nice capture. 7', '2009-12-02 21:50:49.000000', NULL, 1),
(5751452, 835570, 110472, '<td valign="top">Adorable. I love the angle this photo was taken at. Well done.</td>', 'Adorable. I love the angle this photo was taken at. Well done.', '2009-12-02 21:54:34.000000', NULL, 1),
(5751701, 836467, 112177, '<td valign="top">I like this it''s creative and interesting</td>', 'I like this it''s creative and interesting', '2009-12-03 01:17:58.000000', NULL, 1),
(5751705, 836574, 112177, '<td valign="top">I like this but it seems like the depth is odd.  I love the age in the hands but with them in the foreground the face seems out of proportion. interesting</td>', 'I like this but it seems like the depth is odd.  I love the age in the hands but with them in the foreground the face seems out of proportion. interesting', '2009-12-03 01:20:37.000000', NULL, 1),
(5751706, 836248, 112177, '<td valign="top">nice.</td>', 'nice.', '2009-12-03 01:21:13.000000', NULL, 1),
(5751708, 836195, 112177, '<td valign="top">Whoa, nice interpretation.</td>', 'Whoa, nice interpretation.', '2009-12-03 01:22:12.000000', NULL, 1),
(5751712, 836510, 112177, '<td valign="top">Why do the the shoes seem out of focus. Is it me, the dots or is it not focused?</td>', 'Why do the the shoes seem out of focus. Is it me, the dots or is it not focused?', '2009-12-03 01:23:36.000000', NULL, 1),
(5751714, 836241, 112177, '<td valign="top">Creative.</td>', 'Creative.', '2009-12-03 01:24:18.000000', NULL, 1),
