(5751728, 836492, 112177, '<td valign="top">I see where you are going here and as nice as it is, the angel takes away from your polka dots and wasn''t that the focus of the challenge?</td>', 'I see where you are going here and as nice as it is, the angel takes away from your polka dots and wasn''t that the focus of the challenge?', '2009-12-03 01:30:48.000000', NULL, 1),
(5751729, 836497, 112177, '<td valign="top">wow</td>', 'wow', '2009-12-03 01:31:08.000000', NULL, 1),
