(5753064, 836470, 554, '<td valign="top">Now that is the perfect amount of dots.</td>', 'Now that is the perfect amount of dots.', '2009-12-03 20:59:41.000000', NULL, 1),
(5753090, 836508, 554, '<td valign="top">That straight on light hurts my eye.  Possibly you can use multi reflected light to avoid this.  Also you might reflect from below to kill the shadows. Good idea and very pretty subject.</td>', 'That straight on light hurts my eye.  Possibly you can use multi reflected light to avoid this.  Also you might reflect from below to kill the shadows. Good idea and very pretty subject.', '2009-12-03 21:07:05.000000', NULL, 1),
(5753103, 836265, 554, '<td valign="top">Very very funny.  You gotta love those eyes and, What A Nose!!!!</td>', 'Very very funny.  You gotta love those eyes and, What A Nose!!!!', '2009-12-03 21:11:43.000000', NULL, 1),
(5753112, 836589, 554, '<td valign="top">Should not have partially covered the fourth dot.....I like it.</td>', 'Should not have partially covered the fourth dot.....I like it.', '2009-12-03 21:14:05.000000', NULL, 1),
(5753249, 836493, 61651, '<td valign="top">Damned clever, beautifully done.</td>', 'Damned clever, beautifully done.', '2009-12-03 22:28:06.000000', NULL, 1),
(5753277, 835571, 62187, '<td valign="top">A super sweet photo: no pun intended. Polka Dots? Not really to me in the traditional sense. But...creative? Yep...extra bonus points for that!</td>', 'A super sweet photo: no pun intended. Polka Dots? Not really to me in the traditional sense. But...creative? Yep...extra bonus points for that!', '2009-12-03 22:45:20.000000', NULL, 1),
