(5758354, 836224, 103142, '<td valign="top">I thought it was pretty cool -- I gave it a 7 because I liked the textures.</td>', 'I thought it was pretty cool -- I gave it a 7 because I liked the textures.', '2009-12-07 15:35:42.000000', NULL, 0),
(5758356, 836118, 103142, '<td valign="top">Nice shot! I like the sun coming through the wings! You sure got hit by the "true meaning of polka dot" crowd. I thought it was a fine interpretation of the challenge.</td>', 'Nice shot! I like the sun coming through the wings! You sure got hit by the "true meaning of polka dot" crowd. I thought it was a fine interpretation of the challenge.', '2009-12-07 15:37:13.000000', NULL, 0),
